    """Total K/V projections if every step recomputes all prior tokens."""
    return sum(range(1, seq_len + 1))

print(kv_projections_without_cache(5))

def kv_projections_without_cache(seq_len: int) -> int:
    total = 0
    for step in range(1, seq_len + 1):
        total += step
    return total

def kv_savings_percent(seq_len: int) -> float:
    """Percent of K/V projection work a cache removes, vs. no caching."""
    with_cache = seq_len
    without_cache = kv_projections_without_cache(seq_len)
    return round((1 - with_cache / without_cache) * 100, 1)

print(kv_savings_percent(5))
